button-demo.example:
"use client";
import "./rams/styles.css";
import { useState } from "react";
import { Button, type ButtonVariant } from "./rams/components/button";
function Mark() {
    return (<svg aria-hidden="true" viewBox="0 0 24 24" fill="none">
      <path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" strokeWidth="var(--rams-detail-preview-button-link-glyph-stroke)" strokeLinecap="round" strokeLinejoin="round"/>
    </svg>);
}
function Shortlist({ variant = "outline" }: {
    variant?: ButtonVariant;
}) {
    const [kept, setKept] = useState(false);
    return (<div style={{ display: "grid", justifyItems: "start", gap: "calc(var(--spacing,var(--rams-detail-native-spacing-fallback))*4)" }}>
      <Button variant={variant} onClick={() => setKept((value) => !value)}>
        {kept ? "Remove from shortlist" : "Keep terrace study"}
      </Button>
      <p role="status" style={{ display: "grid", margin: 0 }}>
        <span aria-hidden="true" style={{ gridArea: "1 / 1", visibility: "hidden" }}>Shortlist: Terrace study / Rosario.</span>
        <span style={{ gridArea: "1 / 1" }}>{kept ? "Shortlist: Terrace study / Rosario." : ""}</span>
      </p>
    </div>);
}
export function ButtonDemo() {
    return (<div style={{
            display: "flex",
            flexWrap: "wrap",
            alignItems: "flex-start",
            gap: "calc(var(--spacing,var(--rams-detail-native-spacing-fallback))*4)",
        }}>
      <Shortlist />
      <Button variant="outline" size="icon" aria-label="Open Pablo Zarate’s work" asChild>
        <a href="https://pablozarate.com">
          <Mark />
        </a>
      </Button>
    </div>);
}
export default ButtonDemo;

