card-with-form.example:
"use client";
import "./rams/styles.css";
import { useId, useState } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from "./rams/components/card";
import { Input } from "./rams/components/input";
import { Textarea } from "./rams/components/textarea";
import { Label } from "./rams/components/label";
import { Button } from "./rams/components/button";
export function CardWithForm() {
    const id = useId(), [saved, setSaved] = useState<{
        title: string;
        note: string;
    } | null>(null);
    return (<div style={{
            display: "grid",
            width: "100%",
            maxWidth: "var(--rams-detail-preview-measure)",
            gap: "var(--rams-detail-space-4)",
        }}>
      <Card>
        <CardHeader>
          <CardTitle>New print record</CardTitle>
          <CardDescription>
            Keep the title and paper note together.
          </CardDescription>
        </CardHeader>
        <form onSubmit={(event) => {
            event.preventDefault();
            const data = new FormData(event.currentTarget);
            setSaved({
                title: String(data.get("title")),
                note: String(data.get("note")),
            });
        }}>
          <CardContent style={{ display: "grid", gap: "var(--rams-detail-space-3)" }}>
            <Label htmlFor={id + "-title"}>Title</Label>
            <Input id={id + "-title"} name="title" defaultValue="Courtyard / 12" required/>
            <Label htmlFor={id + "-note"}>Paper note</Label>
            <Textarea id={id + "-note"} name="note" defaultValue="160 gsm, short grain." required/>
          </CardContent>
          <CardFooter style={{ marginBlockStart: "var(--rams-detail-space-4)" }}>
            <Button type="submit">Keep record</Button>
          </CardFooter>
        </form>
      </Card>
      {saved && (<section aria-label="Saved print record">
          <h3 style={{ fontWeight: "var(--type-title-weight)" }}>{saved.title}</h3>
          <p>{saved.note}</p>
        </section>)}
    </div>);
}
export default CardWithForm;

