"use client";
import "./rams/styles.css";
import { useId, useState } from "react";
import { Checkbox } from "./rams/components/checkbox";
import { Label } from "./rams/components/label";
import { NativeSelect } from "./rams/components/native-select";
const checkboxRow = {
    display: "flex",
    alignItems: "center",
    gap: "var(--rams-detail-space-3)",
    minInlineSize: 0,
} as const;
export function CheckboxDemo() {
    const id = useId();
    const [selected, setSelected] = useState([true, false]);
    const [tone, setTone] = useState<"accent" | "neutral">("accent");
    const total = selected.filter(Boolean).length;
    return (<div role="group" aria-label="Print sheets" style={{
            display: "grid",
            gap: "var(--rams-detail-space-3)",
            inlineSize: "100%",
            minInlineSize: 0,
            maxInlineSize: "var(--rams-detail-preview-measure)",
        }}>
      <div style={{ display: "grid", gap: "var(--rams-detail-space-1)", justifySelf: "start", maxInlineSize: "100%" }}>
        <Label htmlFor={id + "-tone"}>Selection tone</Label>
        <NativeSelect id={id + "-tone"} value={tone} onChange={event => setTone(event.target.value as "accent" | "neutral")}>
          <option value="accent">System selection</option>
          <option value="neutral">Surface ink</option>
        </NativeSelect>
      </div>
      <div style={checkboxRow}>
        <Checkbox id={id} tone={tone} checked={total === 2 ? true : total ? "indeterminate" : false} onCheckedChange={(value) => setSelected([value === true, value === true])}/>
        <Label htmlFor={id}>Include both print sheets</Label>
      </div>
      {["Terrace / 01", "Courtyard / 02"].map((title, index) => (<div key={title} style={checkboxRow}>
          <Checkbox id={id + "-" + index} tone={tone} checked={selected[index]} onCheckedChange={(value) => setSelected((current) => current.map((checked, i) => i === index ? value === true : checked))}/>
          <Label htmlFor={id + "-" + index}>{title}</Label>
        </div>))}
    </div>);
}
export default CheckboxDemo;

