"use client";
import "./rams/styles.css";
import { useId, useState } from "react";
import * as Command from "./rams/components/command";
import * as Popover from "./rams/components/popover";
import * as Drawer from "./rams/components/drawer";
import { useCompactSurface } from "./rams/components/use-media-query";
import { Button } from "./rams/components/button";
import { Label } from "./rams/components/label";
const archive = [
    "Barranca / 03",
    "Patio / 07",
    "River grid / 14",
    "Terrace / 12",
];
function ArchiveChoices({ onChoose }: {
    onChoose: (value: string) => void;
}) {
    return (<Command.Command label="Rosario editions">
      <Command.CommandInput aria-label="Find an edition" placeholder="Search edition titles…"/>
      <Command.CommandList>
        <Command.CommandEmpty>No matching editions.</Command.CommandEmpty>
        <Command.CommandGroup heading="Rosario editions">
          {archive.map((title) => (<Command.CommandItem key={title} value={title} onSelect={() => onChoose(title)}>
              {title}
            </Command.CommandItem>))}
        </Command.CommandGroup>
      </Command.CommandList>
    </Command.Command>);
}
const fieldLayout = {
    display: "grid",
    gap: "var(--rams-detail-preview-element-gap)",
    inlineSize: "100%",
    maxInlineSize: "var(--rams-detail-preview-measure)",
} as const;
export function ComboboxResponsive() {
    const id = useId(), isMobile = useCompactSurface(), [mobilePresentation, setMobilePresentation] = useState(false), [open, setOpen] = useState(false), [selected, setSelected] = useState<string | null>(null);
    function changeOpen(next: boolean) {
        if (next)
            setMobilePresentation(isMobile);
        setOpen(next);
    }
    function choose(value: string) {
        setSelected(value);
        setOpen(false);
    }
    const trigger = (<Button id={id} role="combobox" aria-label="Edition" aria-expanded={open} variant="outline">
      {selected ?? "Choose an edition"}
    </Button>);
    return (<div style={fieldLayout}>
      <Label htmlFor={id}>Edition</Label>
      {mobilePresentation ? (<Drawer.Drawer open={open} onOpenChange={changeOpen}>
          <Drawer.DrawerTrigger asChild>{trigger}</Drawer.DrawerTrigger>
          <Drawer.DrawerContent>
            <Drawer.DrawerHeader>
              <Drawer.DrawerTitle>Choose an edition</Drawer.DrawerTitle>
              <Drawer.DrawerDescription>
                Search the Rosario print archive.
              </Drawer.DrawerDescription>
            </Drawer.DrawerHeader>
            <ArchiveChoices onChoose={choose}/>
          </Drawer.DrawerContent>
        </Drawer.Drawer>) : (<Popover.Popover open={open} onOpenChange={changeOpen}>
          <Popover.PopoverTrigger asChild>{trigger}</Popover.PopoverTrigger>
          <Popover.PopoverContent aria-label="Choose an edition" style={{
                width: "var(--radix-popover-trigger-width)",
                maxWidth: "var(--radix-popover-content-available-width)",
            }}>
            <ArchiveChoices onChoose={choose}/>
          </Popover.PopoverContent>
        </Popover.Popover>)}
    </div>);
}
export default ComboboxResponsive;

