const papers = [
    "Cotton / 240 gsm",
    "Uncoated / 180 gsm",
    "Linen / 200 gsm",
    "Recycled / 170 gsm",
];
const fieldLayout = {
    display: "grid",
    gap: "var(--rams-detail-preview-element-gap)",
    inlineSize: "100%",
    maxInlineSize: "var(--rams-detail-preview-measure)",
} as const;
export function ComboboxDropdownMenu() {
    const trigger = useRef<HTMLButtonElement>(null), openingPalette = useRef(false), [editing, setEditing] = useState(false), [paper, setPaper] = useState<string | null>(null);
    return (<div style={{ ...fieldLayout, gap: "var(--rams-detail-preview-scene-gap)" }}>
