      <div>
        {paper ? (<Badge variant="secondary">{paper}</Badge>) : (<span>No paper label</span>)}
      </div>
      <Menu.DropdownMenu>
        <Menu.DropdownMenuTrigger asChild>
          <Button ref={trigger} variant="outline">
            Record actions
          </Button>
        </Menu.DropdownMenuTrigger>
        <Menu.DropdownMenuContent onCloseAutoFocus={(event) => {
            if (openingPalette.current) {
                event.preventDefault();
                openingPalette.current = false;
            }
        }}>
          <Menu.DropdownMenuItem onSelect={() => {
            openingPalette.current = true;
            setEditing(true);
        }}>
            Assign a paper label…
          </Menu.DropdownMenuItem>
          <Menu.DropdownMenuItem disabled={!paper} onSelect={() => setPaper(null)}>
            Clear paper label
          </Menu.DropdownMenuItem>
        </Menu.DropdownMenuContent>
