      <Command.CommandDialog open={editing} onOpenChange={setEditing} title="Paper labels" description="Choose the stock attached to this print record." contentProps={{
            onCloseAutoFocus: (event) => {
                event.preventDefault();
                const active = document.activeElement;
                if (active === document.body || !active?.isConnected)
                    trigger.current?.focus({ preventScroll: true });
            },
        }}>
        <Command.CommandInput aria-label="Find a paper label" placeholder="Search paper labels…"/>
        <Command.CommandList>
          <Command.CommandEmpty>No matching labels.</Command.CommandEmpty>
          <Command.CommandGroup heading="Paper stocks">
            {papers.map((item) => (<Command.CommandItem key={item} value={item} onSelect={() => {
                setPaper(item);
                setEditing(false);
            }}>
                {item}
              </Command.CommandItem>))}
          </Command.CommandGroup>
        </Command.CommandList>
      </Command.CommandDialog>
    </div>);
}
export default ComboboxDropdownMenu;

