"use client";
import "./rams/styles.css";
import { useEffect, useId, useState } from "react";
import * as G from "./rams/components/input-group";
import { Label } from "./rams/components/label";
import { Spinner } from "./rams/components/spinner";
const prints = [
    "Barranca / 03",
    "Patio / 07",
    "River grid / 14",
    "Terrace / 12",
];
const previewLayout = {
    inlineSize: "100%",
    maxInlineSize: "var(--rams-detail-preview-measure-wide)",
    display: "grid",
    gap: "var(--rams-detail-preview-element-gap)",
} as const;
function SearchGlyph() {
    return (<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" style={{ strokeWidth: "var(--rams-detail-field-search-glyph-stroke)" }}>
      <circle cx="10" cy="10" r="6"/>
      <path d="m14.5 14.5 5 5"/>
    </svg>);
}
export function InputGroupSpinner() {
    const id = useId(), [query, setQuery] = useState(""), [pending, setPending] = useState(false), [matches, setMatches] = useState(prints);
    useEffect(() => {
        if (!query.trim()) {
            setMatches(prints);
            setPending(false);
            return;
        }
        setPending(true);
        const task = window.setTimeout(() => {
            setMatches(prints.filter((title) => title.toLowerCase().includes(query.toLowerCase())));
            setPending(false);
        }, 350);
        return () => window.clearTimeout(task);
    }, [query]);
    return (<div style={previewLayout}>
      <Label htmlFor={id}>Search the print archive</Label>
      <G.InputGroup>
        <G.InputGroupInput id={id} value={query} onChange={(e) => setQuery(e.target.value)} aria-controls={id + "-results"}/>
        <G.InputGroupAddon>
          <SearchGlyph />
        </G.InputGroupAddon>
        {pending && (<G.InputGroupAddon align="inline-end">
            <Spinner aria-label="Searching the archive"/>
          </G.InputGroupAddon>)}
      </G.InputGroup>
      <section id={id + "-results"} aria-label="Archive results" aria-live="polite" aria-busy={pending}>
        {matches.length ? (<ul>
            {matches.map((title) => (<li key={title}>{title}</li>))}
          </ul>) : (<p>No matching prints.</p>)}
      </section>
    </div>);
}
export default InputGroupSpinner;

