"use client";
import "./rams/styles.css";
import { useRef, useState, type ReactNode } from "react";
import { Button } from "./rams/components/button";
import { Toggle } from "./rams/components/toggle";
import * as G from "./rams/components/button-group";
import { ScrollArea } from "./rams/components/scroll-area";
const actionLayout = {
    width: "100%",
    maxWidth: "var(--rams-detail-preview-measure-full)",
    display: "grid",
    gap: "var(--rams-detail-docs-space-standard)",
};
function ActionStrip({ label, children, wrap = false, }: {
    label: string;
    children: ReactNode;
    wrap?: boolean;
}) {
    return (<ScrollArea scrollbars="horizontal" type="auto" style={{ width: "100%", maxWidth: "var(--rams-detail-preview-measure-full)" }} viewportProps={{ "aria-label": label }}>
      <div style={{
            width: wrap ? "100%" : "max-content",
            minWidth: 0,
            padding: "var(--rams-detail-docs-space-tight)",
            paddingBlockEnd: "calc(var(--rams-detail-docs-space-tight) + var(--rams-detail-button-group-preview-scroll-reserve))",
        }}>
        {children}
      </div>
    </ScrollArea>);
}
function UndoGlyph() {
    return (<svg aria-hidden="true" viewBox="0 0 24 24" fill="none">
      <path d="M9 5 4 10l5 5M4 10h10a5 5 0 0 1 0 10" stroke="currentColor" strokeWidth="var(--rams-detail-preview-button-group-glyph-stroke)"/>
    </svg>);
}
const initialProof = { kept: false, archived: false };
export function ButtonGroupDemo() {
    const [state, setState] = useState({
        current: initialProof,
        history: [] as (typeof initialProof)[],
    }), keep = useRef<HTMLButtonElement>(null);
    function change(key: "kept" | "archived") {
        setState((previous) => ({
            history: [...previous.history, previous.current],
            current: { ...previous.current, [key]: !previous.current[key] },
        }));
    }
    function undo() {
        if (state.history.length === 1)
            keep.current?.focus({ preventScroll: true });
        setState((previous) => previous.history.length
            ? {
                current: previous.history.at(-1)!,
                history: previous.history.slice(0, -1),
            }
            : previous);
    }
    return (<div style={actionLayout}>
      <ActionStrip label="Edition action controls">
        <G.ButtonGroup aria-label="Edition actions">
          <Button variant="outline" size="icon" aria-label="Undo edition action" disabled={!state.history.length} onClick={undo}>
            <UndoGlyph />
          </Button>
          <Toggle ref={keep} variant="outline" pressed={state.current.kept} onPressedChange={() => change("kept")}>
            Shortlist
          </Toggle>
          <Button variant="outline" onClick={() => change("archived")}>
            {state.current.archived ? "Queue" : "Archive"}
          </Button>
        </G.ButtonGroup>
      </ActionStrip>
      <section aria-label="Current edition">
        <h3>Terrace / 12</h3>
        <p>
          {state.current.kept ? "On the shortlist" : "Not shortlisted"} ·{" "}
          {state.current.archived ? "Archived" : "In the print queue"}
        </p>
      </section>
    </div>);
}
export default ButtonGroupDemo;

