"use client";
import "./rams/styles.css";
import { useRef, useState, type ReactNode } from "react";
import { Button } from "./rams/components/button";
import * as G from "./rams/components/button-group";
import { ScrollArea } from "./rams/components/scroll-area";
function ActionStrip({ label, children, wrap = false, }: {
    label: string;
    children: ReactNode;
    wrap?: boolean;
}) {
    return (<ScrollArea scrollbars="horizontal" type="auto" style={{ width: "100%", maxWidth: "var(--rams-detail-preview-measure-full)" }} viewportProps={{ "aria-label": label }}>
      <div style={{
            width: wrap ? "100%" : "max-content",
            minWidth: 0,
            padding: "var(--rams-detail-docs-space-tight)",
            paddingBlockEnd: "calc(var(--rams-detail-docs-space-tight) + var(--rams-detail-button-group-preview-scroll-reserve))",
        }}>
        {children}
      </div>
    </ScrollArea>);
}
function SheetCounter({ label, size = "default", orientation = "horizontal", }: {
    label: string;
    size?: "sm" | "default" | "lg";
    orientation?: "horizontal" | "vertical";
}) {
    const [count, setCount] = useState(12), minus = useRef<HTMLButtonElement>(null), plus = useRef<HTMLButtonElement>(null);
    function change(delta: number) {
        const next = Math.max(1, Math.min(24, count + delta));
        if (next === 1 && document.activeElement === minus.current)
            plus.current?.focus({ preventScroll: true });
        if (next === 24 && document.activeElement === plus.current)
            minus.current?.focus({ preventScroll: true });
        setCount(next);
    }
    return (<div style={{ display: "grid", gap: "var(--rams-detail-docs-space-tight)", justifyItems: "start" }}>
      <p>{label}</p>
      <G.ButtonGroup orientation={orientation} aria-label={label + " sheet count"}>
        <Button ref={minus} variant="outline" size={size} aria-label="Remove one sheet" disabled={count === 1} onClick={() => change(-1)}>
          -
        </Button>
        <G.ButtonGroupText>
          <output aria-label={label + " count"}>
            {count}
          </output>
        </G.ButtonGroupText>
        <Button ref={plus} variant="outline" size={size} aria-label="Add one sheet" disabled={count === 24} onClick={() => change(1)}>
          +
        </Button>
      </G.ButtonGroup>
    </div>);
}
export function ButtonGroupSize() {
    return (<ActionStrip label="Button size comparison" wrap>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "var(--rams-detail-preview-reading-section-gap)", alignItems: "start" }}>
        <SheetCounter label="Small" size="sm"/>
        <SheetCounter label="Default"/>
        <SheetCounter label="Large" size="lg"/>
      </div>
    </ActionStrip>);
}
export default ButtonGroupSize;

