const editionNames = [
    "Terrace",
    "Barranca",
    "Patio",
    "River grid",
    "Trama",
    "Delta",
    "Sur",
    "Río",
    "Galería",
    "Umbral",
    "Vereda",
    "Pliegue",
    "Litoral",
    "Pampa",
    "Costanera",
    "Ceibo",
];
const editions = editionNames.map((title, index) => ({
    number: index + 1,
    title: title + " / " + String(index + 1).padStart(2, "0"),
}));
export function PaginationDemo() {
    const [page, setPage] = useState(2), current = useRef<HTMLButtonElement>(null), pending = useRef(false), pages = Math.ceil(editions.length / 2), start = Math.max(1, Math.min(page - 1, pages - 2)), numbers = [start, start + 1, start + 2];
