const layout = {
    width: "100%",
    maxWidth: "var(--rams-detail-preview-measure-wide)",
    minWidth: 0,
    display: "grid",
    gap: "var(--rams-detail-empty-content-gap)",
} as const;
const summaryStyle = {
    alignItems: "flex-start",
    padding: 0,
    textAlign: "start",
} as const;
const summaryHeaderStyle = { alignItems: "flex-start" } as const;
function TrayGlyph() {
    return (<svg aria-hidden="true" viewBox="0 0 24 24" fill="none">
      <path d="M3 6h18v14H3zM3 14h5l2 3h4l2-3h5M7 3h10" stroke="currentColor" style={{ strokeWidth: "var(--rams-detail-empty-icon-stroke)" }}/>
    </svg>);
}
export function EmptyDemo() {
    const id = useId(), [editions, setEditions] = useState<string[]>([]), [mode, setMode] = useState<"create" | "import" | null>(null), [draft, setDraft] = useState(""), [error, setError] = useState(""), [help, setHelp] = useState(false), create = useRef<HTMLButtonElement>(null), input = useRef<HTMLInputElement | null>(null), textarea = useRef<HTMLTextAreaElement | null>(null), pending = useRef<"create" | "input" | null>(null);
