            (mode === "import" ? textarea.current : input.current)?.focus();
        pending.current = null;
    }, [mode, editions]);
    function begin(next: "create" | "import") {
        setError("");
        if (mode === next) {
            (next === "import" ? textarea.current : input.current)?.focus();
            return;
        }
        pending.current = "input";
        setMode(next);
    }
