                }}>
                <span style={{ minWidth: 0, maxWidth: "100%", overflowWrap: "anywhere" }}>{name}</span>
                <Button variant="outline" size="sm" aria-label={"Remove " + name} onClick={() => remove(name)}>
                  Remove
                </Button>
              </li>))}
          </ul>
        </>) : (<E.Empty style={summaryStyle}>
