          {mode === "import" ? (<Textarea ref={textarea} id={id} maxLength={1200} value={draft} onChange={(event) => setDraft(event.target.value)} aria-invalid={!!error || undefined} aria-describedby={id + "-help" + (error ? " " + id + "-error" : "")}/>) : (<Input ref={input} id={id} maxLength={60} value={draft} onChange={(event) => setDraft(event.target.value)} aria-invalid={!!error || undefined} aria-describedby={error ? id + "-error" : undefined}/>)}
