date-picker-with-presets.example:
"use client";
import "./rams/styles.css";
import { useId, useState } from "react";
import { Calendar } from "./rams/components/calendar";
import { Button } from "./rams/components/button";
import { Label } from "./rams/components/label";
import { Popover, PopoverTrigger, PopoverContent } from "./rams/components/popover";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "./rams/components/select";
const openingDay = new Date(2026, 10, 9);
function dateLabel(date: Date | undefined) {
    return date
        ? new Intl.DateTimeFormat("en", {
            day: "numeric",
            month: "short",
            year: "numeric",
        }).format(date)
        : "Choose a date";
}
const layout = {
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr)",
    gap: "var(--rams-detail-preview-scene-gap)",
    width: "100%",
    maxWidth: "var(--rams-detail-preview-measure-full)",
} as const;
const datePickerLayout = {
    ...layout,
    gap: "var(--rams-detail-docs-space-standard)",
    maxWidth: "var(--rams-detail-preview-measure-full)",
};
const milestones = [
    { key: "proof", name: "First proof", date: openingDay },
    { key: "bindery", name: "Bindery handoff", date: new Date(2026, 10, 12) },
    { key: "pickup", name: "Edition pickup", date: new Date(2026, 10, 16) },
    {
        key: "dispatch",
        name: "Print-room dispatch",
        date: new Date(2026, 10, 20),
    },
];
export function DatePickerWithPresets() {
    const id = useId(), [date, setDate] = useState<Date>(), [month, setMonth] = useState(openingDay), [preset, setPreset] = useState("");
    return (<section style={datePickerLayout} aria-label="Edition milestones">
      <h3>Edition milestones</h3>
      <Popover>
        <PopoverTrigger asChild>
          <Button variant="outline">
            {date ? dateLabel(date) : "Choose milestone date"}
          </Button>
        </PopoverTrigger>
        <PopoverContent aria-label="Choose edition milestone" align="start" style={{
            width: "max-content",
            display: "grid",
            gridTemplateColumns: "minmax(0, 1fr)",
            gap: "var(--rams-detail-docs-space-standard)",
        }}>
          <Label htmlFor={id}>Workshop milestone</Label>
          <Select value={preset} onValueChange={(key) => {
            const milestone = milestones.find((row) => row.key === key);
            if (milestone) {
                setPreset(key);
                setDate(milestone.date);
                setMonth(milestone.date);
            }
        }}>
            <SelectTrigger id={id}>
              <SelectValue placeholder="Choose a milestone"/>
            </SelectTrigger>
            <SelectContent>
              {milestones.map((row) => (<SelectItem key={row.key} value={row.key}>
                  {row.name}
                </SelectItem>))}
            </SelectContent>
          </Select>
          <Calendar mode="single" selected={date} onSelect={(next) => {
            setDate(next);
            setPreset(milestones.find((row) => next?.getTime() === row.date.getTime())
                ?.key ?? "");
        }} month={month} onMonthChange={setMonth} aria-label="Milestone date"/>
          <p role="status">
            {date ? dateLabel(date) : "Choose a milestone or a calendar day."}
          </p>
        </PopoverContent>
      </Popover>
    </section>);
}
export default DatePickerWithPresets;

