            <Select value={series} onValueChange={(value) => setSeries(value as "folded" | "stitched")}>
              <SelectTrigger id={`${id}-series`}>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="folded">Folded sheets</SelectItem>
                <SelectItem value="stitched">Stitched sheets</SelectItem>
              </SelectContent>
            </Select>
          </div>)}
        <div style={{
            display: "grid",
            gap: "calc(var(--rams-detail-preview-space-step-fallback) * 2)",
            flex: "1 1 var(--rams-detail-preview-native-chart-control-basis)",
            minWidth: 0,
        }}>
          <Label htmlFor={`${id}-window`}>Production window</Label>
          <Select value={window} onValueChange={setWindow}>
            <SelectTrigger id={`${id}-window`}>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="90">90 sample days · Sep 1–Nov 29, 2026</SelectItem>
              <SelectItem value="30">30 sample days · Oct 31–Nov 29, 2026</SelectItem>
              <SelectItem value="7">7 sample days · Nov 23–29, 2026</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>
      <output aria-live="polite" aria-label={kind === "area" ? "Cumulative sample sheets" : "Visible sample sheets"}>
        <span data-rams-numeric style={{ whiteSpace: "nowrap" }}>
          {total.toLocaleString("en-US")}
        </span>{" "}
        {kind === "area"
            ? "cumulative sheets in the sample"
            : `${formats[series].label.toLowerCase()} sheets`}
      </output>
      <ChartContainer ref={chartNode} config={formats} style={{ aspectRatio: "auto", height: "var(--rams-detail-preview-native-chart-height)" }}>
        {kind === "bar" ? (<BarChart key={`${window}-${series}`} {...plotProps}>
            {axes}
            <Bar dataKey={series} fill={`var(--color-${series})`} radius={[chartGeometry.marks.barCornerRadius, chartGeometry.marks.barCornerRadius, 0, 0]} {...motion}/>
          </BarChart>) : kind === "line" ? (<LineChart key={`${window}-${series}`} {...plotProps}>
            {axes}
            <Line type="monotone" dataKey={series} stroke={`var(--color-${series})`} strokeWidth={chartGeometry.marks.strokeWidth} dot={false} activeDot={{ r: chartGeometry.marks.activeDotRadius }} {...motion}/>
          </LineChart>) : (<AreaChart key={window} {...plotProps}>
            {axes}
            <Area type="monotone" dataKey="folded" stackId="issued" stroke="var(--color-folded)" fill="var(--color-folded)" fillOpacity={chartGeometry.marks.foldedFillOpacity} strokeWidth={chartGeometry.marks.strokeWidth} {...motion}/>
            <Area type="monotone" dataKey="stitched" stackId="issued" stroke="var(--color-stitched)" fill="var(--color-stitched)" fillOpacity={chartGeometry.marks.stitchedFillOpacity} strokeWidth={chartGeometry.marks.strokeWidth} strokeDasharray={chartGeometry.marks.stitchedDash} {...motion}/>
            <ChartLegend content={<ChartLegendContent />}/>
          </AreaChart>)}
      </ChartContainer>
      <p style={{
            fontSize: "var(--type-caption-size)",
            color: "var(--muted-foreground, var(--rams-muted))",
        }}>
        {dayLabel(data[0].day)}–{dayLabel(data.at(-1)!.day)}, 2026
      </p>
      <div className="rams-chart__sr">
        <table aria-label={`${heading} data`}>
          <thead>
            <tr>
              <th scope="col">Date</th>
              <th scope="col">Folded sheets</th>
              <th scope="col">Stitched sheets</th>
            </tr>
          </thead>
          <tbody>
            {data.map((row) => (<tr key={row.day}>
                <th scope="row">{dayLabel(row.day)}</th>
                <td>{row.folded}</td>
                <td>{row.stitched}</td>
              </tr>))}
          </tbody>
        </table>
      </div>
    </section>);
}
export function ChartLineInteractive() {
    return <PrintLogChart kind="line"/>;
}
export default ChartLineInteractive;

radio-group-demo.example:
"use client";
import "./rams/styles.css";
import { useId, useState, type CSSProperties, type ComponentType } from "react";
import { RadioGroup, RadioGroupItem } from "./rams/components/radio-group";
import { Button } from "./rams/components/button";
import { NativeSelect } from "./rams/components/native-select";
const patterns = [
    {
        value: "parallel",
        label: "Parallel fold",
        description: "Three panels following the same grain.",
    },
    {
        value: "cross",
        label: "Cross fold",
        description: "Four panels around a central meeting point.",
    },
    {
        value: "gate",
        label: "Gate fold",
        description: "Two narrow leaves open to a wide centre.",
    },
];
const frame: CSSProperties = {
    display: "grid",
    gap: "var(--rams-detail-space-3)",
    minInlineSize: 0,
    maxInlineSize: "var(--rams-detail-preview-measure)",
    inlineSize: "100%",
    marginInline: "auto",
    color: "var(--rams-detail-foreground)",
};
const labelText: CSSProperties = {
    fontFamily: "var(--type-control-family)",
    fontSize: "var(--type-control-size)",
    lineHeight: "var(--type-control-leading)",
    letterSpacing: "var(--type-control-tracking)",
    fontWeight: "var(--rams-detail-label-weight)",
};
const helpText: CSSProperties = {
    color: "var(--rams-detail-text-muted)",
    fontFamily: "var(--type-caption-family)",
    fontSize: "var(--type-caption-size)",
    lineHeight: "var(--type-caption-leading)",
};
function NativeFoldControls({ value, onValueChange, tone, }: {
    value: string;
    onValueChange: (value: string) => void;
    tone?: "accent" | "neutral";
}) {
    const id = useId();
    return (<RadioGroup aria-label="Fold pattern" name="fold-pattern" tone={tone} value={value} onValueChange={onValueChange}>
      {patterns.map((item, index) => (<label key={item.value} style={{
                display: "flex",
                alignItems: "center",
                gap: "var(--rams-detail-space-3)",
                padding: "var(--rams-detail-space-2)",
                border: "var(--rams-detail-primitive-border-width) solid var(--rams-detail-border)",
                borderRadius: "var(--radius-control)",
                cursor: "pointer",
            }}>
          <RadioGroupItem value={item.value} aria-labelledby={`${id}-label-${index}`} aria-describedby={`${id}-description-${index}`}/>
          <span style={{ display: "grid", gap: "var(--rams-detail-selection-description-gap)", minInlineSize: 0 }}>
            <strong id={`${id}-label-${index}`} style={labelText}>
              {item.label}
            </strong>
            <span id={`${id}-description-${index}`} style={helpText}>
              {item.description}
            </span>
          </span>
        </label>))}
    </RadioGroup>);
}
function FoldStudy({ Control, kind, }: {
    Control: ComponentType<{
        value: string;
        onValueChange: (value: string) => void;
        tone?: "accent" | "neutral";
    }>;
    kind: "native" | "motion";
}) {
    const [pattern, setPattern] = useState("parallel");
    const [tone, setTone] = useState<"accent" | "neutral">("accent");
    const option = patterns.find((item) => item.value === pattern)!;
    const creases = pattern === "cross"
        ? "M180 24v172M36 110h288"
        : pattern === "gate"
            ? "M108 24v172M252 24v172"
            : "M132 24v172M228 24v172";
    return (<form data-radio-fold-scene={kind} style={frame} onReset={() => { setPattern("parallel"); setTone("accent"); }}>
      <header style={{ display: "grid", gap: "var(--rams-detail-space-1)" }}>
        <span style={helpText}>Buenos Aires / paper studies</span>
        <strong style={{
            fontFamily: "var(--type-title-family)",
            fontSize: "var(--type-title-size)",
            lineHeight: "var(--type-title-leading)",
            fontWeight: "var(--type-title-weight)",
        }}>
          One sheet, three openings
        </strong>
      </header>
      <svg viewBox="0 0 360 220" role="img" aria-label={`${option.label} diagram: ${option.description}`} style={{
            display: "block",
            inlineSize: "100%",
            blockSize: "auto",
            border: "var(--rams-detail-primitive-border-width) solid var(--rams-detail-border)",
            borderRadius: "var(--radius-control)",
            background: "var(--rams-detail-surface)",
        }}>
        <g fill="none" stroke="currentColor">
          <rect x="36" y="24" width="288" height="172"/>
          <path d="M55 149Q88 71 153 112T299 70" strokeWidth="var(--rams-detail-preview-plate-line-stroke)"/>
          <path d="M55 165Q88 87 153 128T299 86"/>
          <path d={creases} strokeDasharray="var(--rams-detail-preview-fold-crease-dash)"/>
        </g>
        <g fill="currentColor" fontFamily="inherit">
          <text x="54" y="50" fontSize="var(--rams-detail-preview-fold-imprint-size)">
            PAPER STUDY / 03
          </text>
          <text x="54" y="183" fontSize="var(--rams-detail-preview-fold-label-size)">
            {option.label.toUpperCase()}
          </text>
        </g>
      </svg>
      <label style={{ display: "grid", gap: "var(--rams-detail-space-1)", justifySelf: "start", maxInlineSize: "100%" }}>
        <span style={labelText}>Selection tone</span>
        <NativeSelect value={tone} onChange={event => setTone(event.target.value as "accent" | "neutral")}>
          <option value="accent">System selection</option>
          <option value="neutral">Surface ink</option>
        </NativeSelect>
      </label>
      <Control value={pattern} onValueChange={setPattern} tone={tone}/>
      <div style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            flexWrap: "wrap",
            gap: "var(--rams-detail-space-3)",
        }}>
        <p role="status" style={{ ...helpText, margin: 0 }}>
          {option.label} · crease lines shown
        </p>
        <Button type="reset" variant="outline">
          Reset fold
        </Button>
      </div>
    </form>);
}
export function NativeFoldPatternDemo() {
    return <FoldStudy Control={NativeFoldControls} kind="native"/>;
}
export default NativeFoldPatternDemo;

integration-form.example:
"use client";
import "./rams/styles.css";
import { useId, useState, type CSSProperties } from "react";
import { useForm } from "react-hook-form";
import { Form, FormField, FormItem, FormLabel, FormControl, FormDescription, FormMessage } from "./rams/components/form";
import { Input } from "./rams/components/input";
import { Button } from "./rams/components/button";
import { Card, CardContent } from "./rams/components/card";
const layout: CSSProperties = { display: "grid", gridTemplateColumns: "minmax(0,1fr)", width: "100%", maxWidth: "var(--rams-detail-preview-measure)", minWidth: 0, gap: "var(--rams-detail-preview-scene-gap)", fontSize: "var(--type-body-size)", lineHeight: "var(--rams-detail-preview-print-scene-leading)" };
const heading: CSSProperties = { margin: 0, fontSize: "var(--type-title-size)", fontWeight: "var(--rams-detail-preview-integration-form-heading-weight)", lineHeight: "var(--type-title-leading)", overflowWrap: "anywhere" };
export function FormIntegration() {
    const id = useId();
    const form = useForm<{
        label: string;
    }>({ defaultValues: { label: "" } });
    const [proofLabel, setProofLabel] = useState("");
    return <Form {...form}><form noValidate aria-labelledby={`${id}-heading`} style={layout} onSubmit={form.handleSubmit(values => setProofLabel(values.label.trim()))}>
    <h2 id={`${id}-heading`} style={heading}>Create a local proof label</h2>
    <FormField control={form.control} name="label" rules={{ validate: value => !value.trim() ? "Enter a proof label." : value.trim().length < 3 ? "Use at least 3 characters." : value.trim().length > 32 ? "Use no more than 32 characters." : true }} render={({ field }) => <FormItem>
      <FormLabel>Proof label</FormLabel><FormControl><Input {...field} required maxLength={32} autoComplete="off"/></FormControl>
      <FormDescription>Use 3–32 characters for the Córdoba worksheet.</FormDescription><FormMessage />
    </FormItem>}/>
    <Button type="submit">Keep label</Button>
    <div role="status">{proofLabel ? <Card role="region" aria-label="Local proof label"><CardContent><p style={{ margin: 0, overflowWrap: "anywhere" }}>{proofLabel}</p></CardContent></Card> : <p style={{ margin: 0 }}>No proof label has been kept.</p>}</div>
  </form></Form>;
}
export default FormIntegration;

integration-combobox.example:
"use client";
import "./rams/styles.css";
import { useId, useState, type CSSProperties } from "react";
import { Combobox, ComboboxInput, ComboboxContent, ComboboxList, ComboboxItem, ComboboxEmpty } from "./rams/components/combobox";
const layout: CSSProperties = { display: "grid", gridTemplateColumns: "minmax(0,1fr)", width: "100%", maxWidth: "var(--rams-detail-preview-measure)", minWidth: 0, gap: "var(--rams-detail-preview-scene-gap)", fontSize: "var(--type-body-size)", lineHeight: "var(--rams-detail-preview-print-scene-leading)" };
const heading: CSSProperties = { margin: 0, fontSize: "var(--type-title-size)", fontWeight: "var(--rams-detail-preview-integration-form-heading-weight)", lineHeight: "var(--type-title-leading)", overflowWrap: "anywhere" };
const paperStocks = ["Rosario — uncoated 90 gsm", "Mendoza — textured 120 gsm", "La Plata — smooth 100 gsm", "Córdoba — recycled 110 gsm"];
export function ComboboxIntegration() {
    const id = useId();
    const [value, setValue] = useState<string | null>(null), [query, setQuery] = useState("");
    const filtered = paperStocks.filter(item => item.toLocaleLowerCase("en").includes(query.trim().toLocaleLowerCase("en")));
    return <section style={layout} aria-labelledby={`${id}-heading`}>
    <h2 id={`${id}-heading`} style={heading}>Choose a worksheet paper stock</h2>
    <label htmlFor={`${id}-stock`}>Paper stock</label>
    <Combobox inputValue={query} items={paperStocks} filteredItems={filtered} value={value} onValueChange={setValue} onInputValueChange={setQuery}>
      <ComboboxInput id={`${id}-stock`} placeholder="Search" autoComplete="off" showClear={value !== null}/>
      <ComboboxContent><ComboboxEmpty>No matching stock.</ComboboxEmpty><ComboboxList>{(item: string) => <ComboboxItem key={item} value={item}>{item}</ComboboxItem>}</ComboboxList></ComboboxContent>
    </Combobox>
    <p role="status" style={{ margin: 0, overflowWrap: "anywhere" }}>Selected stock: {value || "none"}.</p>
  </section>;
}
export default ComboboxIntegration;
